let $=s=>document.querySelector(s), revisions=window.REVISIONS, concept=new URLSearchParams(location.search).get('concept')||'A';
let selected=0,presentation='closed',previous='half',file=null,tool=null,toolTabs=[],readScroll=new Map(),originFocus=null;
let drafts=new Map(),tasks=new Map();
let task=()=>tasks.get(tool);
let taskRevision=()=>revisions.find(r=>r.id===task()?.source)||revision();
let useHost=()=>concept==='B'&&innerWidth>=880&&presentation!=='full'&&$('#destination').hidden;
let commands=['Inspect revision','Edit description','New child revision','Move revision','Bookmarks','Remotes','Operation history','Workspace settings'];
let esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
let revision=()=>revisions[selected];
document.body.dataset.concept=concept;
document.querySelector(`a[href="?concept=${concept}"]`)?.setAttribute('aria-current','page');
$('#hint').textContent=concept==='A'?'Graph first. Repository tools open above the workspace.':concept==='B'?'Keep revision inspection beside a bounded tools workspace.':'Review a source revision, then choose a task and destination.';
$('#rows').innerHTML=revisions.map((r,i)=>`<button class="row" data-select="${i}" aria-label="${esc(r.title)}"><span class="rail"></span><span class="id">${r.id}</span><span class="title">${esc(r.title)}</span></button>`).join('');
if(concept==='B'){$('#host').hidden=false;renderHost()}
if(concept==='C'){let rail=document.createElement('nav');rail.id='task-rail';rail.setAttribute('aria-label','Task navigation');rail.innerHTML='<button data-tool="Review queue">Review</button><button data-tool="Move revision">Move</button><button data-tool="Bookmarks">Refs</button>';document.body.append(rail)}
function route(kind,extra={}){let method=kind==='tool'&&history.state?.kind==='tool'?'replaceState':'pushState';history[method]({kind,selected,file,previous,tool,task:task(),...extra},'',`${location.pathname}?concept=${concept}#${kind}/${revision().id}${file?'/file/'+encodeURIComponent(file):''}${kind==='tool'?'/'+encodeURIComponent(tool):''}`)}
function select(i){selected=i;file=null;presentation='half';previous='half';renderSheet();document.querySelectorAll('.row').forEach((e,j)=>e.classList.toggle('selected',i===j));}
function files(){return revision().files.map(f=>`<button class="file" data-file="${esc(f)}"><span>${esc(f)}</span><span>Inspect</span></button>`).join('')}
function actions(){return '<div class="actions">'+['Edit description','New child revision','Move revision'].map(t=>`<button data-tool="${t}">${t}</button>`).join('')+'</div>'}
function renderSheet(){$('#sheet').hidden=presentation==='closed';$('#sheet').classList.toggle('collapsed',presentation==='collapsed');$('#handle').setAttribute('aria-expanded',presentation==='half');$('#summary').innerHTML=`<h2>${esc(revision().title)}</h2><span class="id">${revision().id}</span>`;$('#preview').innerHTML=`<p class="muted">Julius Koskela · Git snapshot revision</p><details><summary>Revision description</summary><p>${esc(revision().title)}</p></details>${actions()}<h3>${revision().files.length} changed files</h3>${files()}<button data-full>Inspect full revision</button>`;}
function full(path){saveReading();if(presentation!=='full')previous=presentation==='collapsed'?'collapsed':'half';file=path??file;presentation='full';originFocus=document.activeElement;route('revision');renderFull()}
function saveReading(){let d=$('#patch');if(d)readScroll.set(revision().id+':'+file,d.scrollTop)}
function patch(text){return text.split('\n').map(l=>`<div class="${l.startsWith('+')?'add':l.startsWith('-')?'remove':''}">${esc(l)||' '}</div>`).join('')}
function lockBackground(locked){$('#workspace').inert=locked;$('#sheet').inert=locked;let rail=$('#task-rail');if(rail)rail.inert=locked}
function renderFull(){lockBackground(true);let r=revision();$('#destination').dataset.taskSource=r.id;$('#destination').hidden=false;$('#destination').innerHTML=`<div class="destination-top"><button data-back>Back to preview</button><h1>${file?'File inspection':'Revision'}</h1><button data-tool="Commands">Commands</button></div><span class="id">${r.id}</span><h2>${esc(r.title)}</h2>${file?`<button data-files>Choose another file</button><h3>${esc(file)}</h3><div class="patch" id="patch" tabindex="0" aria-label="File diff">${patch(r.diffs[file]||'No patch in bounded snapshot.')}</div>`:`<p class="muted">Julius Koskela · ${r.files.length} changed files</p>${actions()}${files()}`}`;if(file)$('#patch').scrollTop=readScroll.get(r.id+':'+file)||0;$('#destination [data-back]').focus({preventScroll:true})}
function toolBody(name){let r=taskRevision(),target=task()?.target;let preview=`data-preview data-preview-source="${r.id}"${target?` data-preview-target="${target}"`:''}`;if(name==='Commands')return `<input aria-label="Find command" placeholder="Find command" id="search">`+commands.map(t=>`<button class="file command" data-tool="${t}">${t}</button>`).join('');if(name==='Move revision')return `<p>Choose a destination for this source. This is a read-only interaction study.</p><div class="source-target"><section><h3>Source</h3><span class="id">${r.id}</span><p>${esc(r.title)}</p></section><section><h3>Destination</h3>${revisions.filter(x=>x.id!==r.id).slice(0,8).map(x=>`<button data-target="${x.id}" class="${target===x.id?'selected-target':''}"><span class="id">${x.id}</span> ${esc(x.title)}</button>`).join('')}</section></div>${target?`<p role="status">Review move: ${r.id} → ${target}. Descendants may be rewritten; conflicts are possible.</p><button ${preview}>Preview move</button>`:''}`;if(name==='Review queue')return `<p>Choose a source revision for review.</p>`+revisions.map((r,i)=>`<button class="file" data-review="${i}"><span class="id">${r.id}</span>${esc(r.title)}</button>`).join('');if(name==='Bookmarks'||name==='Remotes'||name==='Operation history'||name==='Workspace settings')return `<p>This ${name.toLowerCase()} destination retains revision <span class="id">${r.id}</span>.</p><p class="muted">The snapshot contains commit history and patch text only. Live ${name.toLowerCase()} data is unavailable.</p><button data-tool="Commands">Choose another tool</button>`;if(name==='Edit description')return `<label>Revision description<textarea data-draft-source="${r.id}" aria-label="Revision description" style="display:block;width:100%;min-height:140px">${esc(drafts.get(r.id)??r.title)}</textarea></label><p class="muted">Read-only snapshot. Save previews the exact target; no IPC is called.</p><button ${preview}>Preview save for ${r.id}</button>`;return `<p>Source revision <span class="id">${r.id}</span>: ${esc(r.title)}</p><p>Preview only; this snapshot cannot change the repository.</p><button ${preview}>Preview ${esc(name.toLowerCase())}</button>`}
function renderModal(){$('#modal-content').dataset.taskSource=taskRevision().id;$('#modal-content').innerHTML=`<h2>${esc(tool)}</h2>${toolBody(tool)}`;if(!$('#modal').open)$('#modal').showModal();$('#modal input, #modal textarea, #modal button')?.focus()}
function openTool(name,context=revision().id){if(name==='Inspect revision'){let i=revisions.findIndex(r=>r.id===context);if(i!==selected)select(i);full();return}saveReading();if(!tasks.has(name)||(!toolTabs.includes(name)&&tasks.get(name).source!==context))tasks.set(name,{source:context,target:null});tool=name;originFocus=document.activeElement;if(concept==='A')renderModal();else if(useHost()){if(!toolTabs.includes(name)){toolTabs.push(name);if(toolTabs.length>3)toolTabs.shift()}renderHost()}else{route('tool');renderToolDestination()}}
function renderTool(){if(concept==='A')renderModal();else if(useHost())renderHost();else renderToolDestination()}
function renderHost(){$('#host').dataset.taskSource=taskRevision().id;$('#host').innerHTML=`<h2>Repository workspace</h2><div class="tabs">${toolTabs.map(t=>`<button data-tool="${t}" aria-pressed="${tool===t}">${esc(t)}</button>`).join('')}</div>${tool?`<div class="actions"><button data-close-host>Close ${esc(tool)}</button><button data-tool="Commands">Add tool</button></div>${toolBody(tool)}`:'<p>Open a command to keep its state beside revision history.</p><button data-tool="Commands">Open tools</button>'}`}
function renderToolDestination(){lockBackground(true);$('#destination').dataset.taskSource=taskRevision().id;$('#destination').hidden=false;$('#destination').innerHTML=`<div class="destination-top"><button data-back>Back</button><h1>${esc(tool)}</h1><button data-tool="Commands">Commands</button></div><p class="muted">${concept==='C'?'Task stack / ':'Workspace / '}${taskRevision().id}</p>${toolBody(tool)}`;$('#destination input, #destination textarea, #destination button')?.focus()}
function restore(){saveReading();lockBackground(false);$('#destination').hidden=true;let s=history.state;if(s?.kind){selected=s.selected;file=s.file;previous=s.previous;if(s.kind==='revision'){presentation='full';renderFull()}else{tool=s.tool;if(s.task)tasks.set(tool,s.task);renderToolDestination()}}else{presentation=previous;renderSheet();if(originFocus?.isConnected)originFocus.focus({preventScroll:true});else document.querySelector('.row.selected')?.focus({preventScroll:true})}}
addEventListener('popstate',restore);
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.select!==undefined)select(+b.dataset.select);if(b.hasAttribute('data-full'))full();if(b.dataset.file){saveReading();file=b.dataset.file;if(presentation==='full'){history.replaceState({...history.state,file},'',`${location.pathname}?concept=${concept}#revision/${revision().id}/file/${encodeURIComponent(file)}`);renderFull()}else full(file)}if(b.hasAttribute('data-files')){saveReading();file=null;history.replaceState({...history.state,file},'',`${location.pathname}?concept=${concept}#revision/${revision().id}`);renderFull()}if(b.dataset.tool)openTool(b.dataset.tool,b.closest('[data-task-source]')?.dataset.taskSource||revision().id);if(b.hasAttribute('data-back'))history.back();if(b.dataset.target){task().target=b.dataset.target;if(history.state?.kind==='tool')history.replaceState({...history.state,task:task()},'');renderTool()}if(b.hasAttribute('data-preview')){let p=document.createElement('p');p.setAttribute('role','status');p.textContent=`Preview ready for ${b.dataset.previewSource}${b.dataset.previewTarget?' → '+b.dataset.previewTarget:''}. No repository changes made.`;b.after(p)}if(b.dataset.review!==undefined){let next=+b.dataset.review;addEventListener('popstate',()=>select(next),{once:true});history.back()}if(b.hasAttribute('data-close-host')){toolTabs=toolTabs.filter(t=>t!==tool);tool=toolTabs.at(-1)||null;renderHost()}});
$('#commands').onclick=()=>openTool('Commands');$('#close-modal').onclick=()=>{$('#modal').close();originFocus?.focus({preventScroll:true})};
let drag=null,moved=false;$('#handle').onpointerdown=e=>{drag=e.clientY;moved=false;e.currentTarget.setPointerCapture(e.pointerId)};$('#handle').onpointermove=e=>{if(drag!==null&&Math.abs(e.clientY-drag)>8)moved=true};$('#handle').onpointerup=e=>{if(drag===null)return;let dy=e.clientY-drag;drag=null;if(Math.abs(dy)>30){presentation=dy>0?'collapsed':'half';renderSheet()}};$('#handle').onpointercancel=()=>{drag=null;moved=true};$('#handle').onclick=()=>{if(!moved){presentation=presentation==='collapsed'?'half':'collapsed';renderSheet()}};
document.addEventListener('input',e=>{if(e.target.matches('textarea'))drafts.set(e.target.dataset.draftSource,e.target.value);if(e.target.id==='search')document.querySelectorAll('.command').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()))});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openTool('Commands',document.activeElement?.closest('[data-task-source]')?.dataset.taskSource||revision().id)}if(e.key==='Escape'&&!$('#modal').open){if(!$('#destination').hidden)history.back();else{presentation=presentation==='half'?'collapsed':'closed';renderSheet()}}});
let match=decodeURIComponent(location.hash).match(/^#(revision|tool)\/([^/]+)(?:\/file\/(.*))?/);if(match){let i=revisions.findIndex(r=>r.id===match[2]);if(i>=0){selected=i;file=match[3]||null;presentation='full';if(match[1]==='tool'){tool=decodeURIComponent(location.hash.split('/').slice(2).join('/'));tasks.set(tool,{source:revision().id,target:null});history.replaceState({kind:'tool',selected,file:null,tool,task:task(),previous:'half'},'');renderToolDestination()}else{history.replaceState({kind:'revision',selected,file,previous:'half'},'');renderFull()}}}
